  default_vacation_reply: { bg:'Здравей, {name}! В отпуска съм до {until}. Ще ти отговоря, когато се върна.', ru:'Привет, {name}! Я в отпуске до {until}. Отвечу, когда вернусь.', uk:'Привіт, {name}! Я у відпустці до {until}. Відповім, коли повернуся.', en:'Hi {name}! I am on vacation until {until}. I will reply when I am back.', de:'Hallo {name}! Ich bin bis {until} im Urlaub. Ich antworte, sobald ich zurück bin.', fr:'Bonjour {name} ! Je suis en vacances jusqu’au {until}. Je répondrai à mon retour.', es:'¡Hola {name}! Estoy de vacaciones hasta el {until}. Responderé cuando vuelva.', 'es-MX':'¡Hola {name}! Estoy de vacaciones hasta el {until}. Te respondo cuando regrese.', it:'Ciao {name}! Sono in vacanza fino al {until}. Risponderò al mio ritorno.', pt:'Olá {name}! Estou de férias até {until}. Respondo quando voltar.', ar:'مرحبًا {name}! أنا في إجازة حتى {until}. سأرد عند عودتي.', hi:'नमस्ते {name}! मैं {until} तक छुट्टी पर हूँ। लौटकर जवाब दूँगा।', ja:'こんにちは {name}さん。{until} まで休暇中です。戻り次第返信します。', ky:'Салам, {name}! Мен {until} чейин өргүүдөмүн. Кайтып келгенде жооп берем.', 'zh-Hant':'{name} 你好！我休假到 {until}，回來後會回覆你。' },
