  tpl_lib_title: { bg:'📚 Библиотека с шаблони', ru:'📚 Библиотека шаблонов', uk:'📚 Бібліотека шаблонів', en:'📚 Template library', de:'📚 Vorlagenbibliothek', fr:'📚 Bibliothèque de modèles', es:'📚 Biblioteca de plantillas', 'es-MX':'📚 Biblioteca de plantillas', it:'📚 Libreria di modelli', pt:'📚 Biblioteca de modelos', ar:'📚 مكتبة القوالب', hi:'📚 टेम्पलेट लाइब्रेरी', ja:'📚 テンプレート集', ky:'📚 Үлгүлөр китепканасы', 'zh-Hant':'📚 範本庫' },
  tpl_lib_note: { bg:'Готови отговори по категории. Променливи: {name} — подател, {time} — час, {date} — дата, {text} — входящият текст, {until} — датата „до" на отпуската.', ru:'Готовые ответы по категориям. Переменные: {name} — отправитель, {time} — время, {date} — дата, {text} — входящий текст, {until} — дата „до" отпуска.', uk:'Готові відповіді за категоріями. Змінні: {name} — відправник, {time} — час, {date} — дата, {text} — вхідний текст, {until} — дата „до" відпустки.', en:'Ready replies by category. Variables: {name} — sender, {time} — time, {date} — date, {text} — incoming text, {until} — vacation end date.', de:'Fertige Antworten nach Kategorie. Variablen: {name} — Absender, {time} — Uhrzeit, {date} — Datum, {text} — eingehender Text, {until} — Urlaubsende.', fr:'Réponses prêtes par catégorie. Variables : {name} — expéditeur, {time} — heure, {date} — date, {text} — texte reçu, {until} — fin des vacances.', es:'Respuestas listas por categoría. Variables: {name} — remitente, {time} — hora, {date} — fecha, {text} — texto entrante, {until} — fin de vacaciones.', 'es-MX':'Respuestas listas por categoría. Variables: {name} — remitente, {time} — hora, {date} — fecha, {text} — texto entrante, {until} — fin de vacaciones.', it:'Risposte pronte per categoria. Variabili: {name} — mittente, {time} — ora, {date} — data, {text} — testo in arrivo, {until} — fine vacanza.', pt:'Respostas prontas por categoria. Variáveis: {name} — remetente, {time} — hora, {date} — data, {text} — texto recebido, {until} — fim das férias.', ar:'ردود جاهزة حسب الفئة. المتغيرات: {name} — المُرسِل، {time} — الوقت، {date} — التاريخ، {text} — النص الوارد، {until} — نهاية الإجازة.', hi:'श्रेणी के अनुसार तैयार जवाब। चर: {name} — प्रेषक, {time} — समय, {date} — तारीख़, {text} — आया हुआ पाठ, {until} — छुट्टी की अंतिम तारीख़।', ja:'カテゴリ別の定型返信。変数: {name} — 送信者、{time} — 時刻、{date} — 日付、{text} — 受信テキスト、{until} — 休暇終了日。', ky:'Категория боюнча даяр жооптор. Өзгөрмөлөр: {name} — жөнөтүүчү, {time} — убакыт, {date} — күн, {text} — кирген текст, {until} — өргүүнүн аяккы күнү.', 'zh-Hant':'依類別的現成回覆。變數：{name} — 寄件者，{time} — 時間，{date} — 日期，{text} — 收到的文字，{until} — 休假結束日。' },
